n_qubits = 5
dev = qml.device("default.qubit", wires=n_qubits, shots=None)

@qml.qnode(dev)
def circuit(inputs, weights):
    # Simple encoding with RY gates
    for i in range(n_qubits):
        qml.RY(inputs[i], wires=i)

    # Simple layer of parameterized rotations
    for i in range(n_qubits):
        qml.RY(weights[i], wires=i)

    # Measure all qubits
    return [qml.expval(qml.PauliZ(i)) for i in range(n_qubits)]

n_qubits = 7
dev = qml.device("default.qubit", wires=n_qubits, shots=None)

@qml.qnode(dev)
def circuit(inputs, weights):
    # Enhanced encoding: distribute inputs with different rotation types
    for i in range(n_qubits):
        if i % 3 == 0:
            qml.RX(inputs[i % len(inputs)], wires=i)
        elif i % 3 == 1:
            qml.RY(inputs[i % len(inputs)], wires=i)
        else:
            qml.RZ(inputs[i % len(inputs)], wires=i)

    # First rotation layer
    for i in range(n_qubits):
        qml.RX(weights[i, 0], wires=i)
        qml.RY(weights[i, 1], wires=i)
        qml.RZ(weights[i, 2], wires=i)

    # First entanglement layer - ring
    for i in range(n_qubits):
        qml.CNOT(wires=[i, (i + 1) % n_qubits])

    # Second rotation layer
    for i in range(n_qubits):
        qml.RX(weights[i, 3], wires=i)
        qml.RY(weights[i, 4], wires=i)

    # Second entanglement layer - skip connections
    for i in range(0, n_qubits, 2):
        qml.CNOT(wires=[i, (i + 2) % n_qubits])

    # Third rotation layer
    for i in range(n_qubits):
        qml.RX(weights[i, 5], wires=i)
        qml.RY(weights[i, 6], wires=i)

    # Measure with multiple operators
    observables = []
    for i in range(n_qubits):
        observables.append(qml.expval(qml.PauliX(i)))
        observables.append(qml.expval(qml.PauliZ(i)))

    return observables

n_qubits = 9
dev = qml.device("default.qubit", wires=n_qubits, shots=None)

@qml.qnode(dev)
def circuit(inputs, weights):
    # Divide qubits into data qubits (0-4) and auxiliary qubits (5-8)
    data_qubits = range(5)
    aux_qubits = range(5, n_qubits)

    # Initialize auxiliary qubits in superposition
    for i in aux_qubits:
        qml.Hadamard(wires=i)

    # Encode data into data qubits
    for i in data_qubits:
        qml.RY(inputs[i], wires=i)

    # First parameterized layer - different for data and aux qubits
    for i in data_qubits:
        qml.RX(weights[i, 0], wires=i)
        qml.RY(weights[i, 1], wires=i)

    for i in aux_qubits:
        qml.RZ(weights[i, 0], wires=i)
        qml.RY(weights[i, 1], wires=i)

    # Controlled operations from data to auxiliary qubits
    for i, data_q in enumerate(data_qubits):
        if i < len(aux_qubits):
            qml.CNOT(wires=[data_q, aux_qubits[i]])

    # Second rotation layer
    for i in range(n_qubits):
        qml.RZ(weights[i, 2], wires=i)

    # Star entanglement within data qubits
    central_qubit = 0
    for i in data_qubits:
        if i != central_qubit:
            qml.CNOT(wires=[central_qubit, i])

    # Star entanglement within auxiliary qubits
    aux_central = 5
    for i in aux_qubits:
        if i != aux_central:
            qml.CNOT(wires=[aux_central, i])

    # Connect data center to auxiliary center
    qml.CNOT(wires=[central_qubit, aux_central])

    # Final rotation layer
    for i in range(n_qubits):
        qml.RX(weights[i, 3], wires=i)
        qml.RY(weights[i, 4], wires=i)

    # Measure both data and selected auxiliary qubits
    # Use a different basis for aux qubits to extract more information
    observables = []
    for i in data_qubits:
        observables.append(qml.expval(qml.PauliZ(i)))
    for i in aux_qubits:
        observables.append(qml.expval(qml.PauliX(i)))

    return observables
